    if (fn.type != VAL_FUNC && fn.type != VAL_CLOSURE) return lua_val_nil();
    lua_Value args[33];
    int n = argc < 32 ? argc : 32;
    args[0] = obj;
    for (int i = 0; i < n; i++) args[i + 1] = argv[i];
    return lua_invoke(fn, n + 1, args);
