    size_t ms = 0, me = 0;
    if (!duo_lp_find_at(s, slen, pat, 0, &ms, &me)) return lua_val_nil();
    size_t mlen = me - ms;
    char* out = malloc(mlen + 1);
    memcpy(out, s + ms, mlen);
